SELECT id, device_code, reading_ts, temp_c, status_bits, NTILE(5) OVER w_ordered AS status_bits_bucket, PERCENT_RANK() OVER w_ordered_2 AS status_bits_percent_rank, COUNT(pressure) OVER w_recent AS device_code_count_pressure FROM device_readings WINDOW w_ordered AS (PARTITION BY YEAR(reading_ts), device_code ORDER BY status_bits DESC, id), w_ordered_2 AS (PARTITION BY device_code ORDER BY status_bits), w_recent AS (PARTITION BY device_code);
